5: // REG-002..024, COM-CSharp_ASPNET. The transport contains only explicitly permitted values.
6: [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
7: public sealed class StudentSaveInput
8: {
9:     public string StudentNo { get; set; } = "";
10:     public string StudentName { get; set; } = "";
11:     public string StudentNameKana { get; set; } = "";
